-- =============================================
-- Tabla: usuario
-- Descripción: Almacena los usuarios del sistema
-- =============================================

CREATE TABLE usuario (
    id SERIAL PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    rol_id INTEGER NOT NULL,
    estado VARCHAR(20) DEFAULT 'Activo' CHECK (estado IN ('Activo', 'Inactivo', 'Bloqueado')),
    ultimo_acceso TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_usuario_rol FOREIGN KEY (rol_id) REFERENCES rol(id) ON DELETE RESTRICT ON UPDATE CASCADE
);

-- Índices para optimización de consultas
CREATE INDEX idx_usuario_email ON usuario(email);
CREATE INDEX idx_usuario_rol ON usuario(rol_id);
CREATE INDEX idx_usuario_estado ON usuario(estado);

-- Comentarios en la tabla y columnas
COMMENT ON TABLE usuario IS 'Tabla de usuarios del sistema de información';
COMMENT ON COLUMN usuario.id IS 'Identificador único del usuario';
COMMENT ON COLUMN usuario.nombre IS 'Nombre completo del usuario';
COMMENT ON COLUMN usuario.email IS 'Correo electrónico único del usuario';
COMMENT ON COLUMN usuario.password IS 'Contraseña encriptada (bcrypt)';
COMMENT ON COLUMN usuario.rol_id IS 'Referencia al rol del usuario';
COMMENT ON COLUMN usuario.estado IS 'Estado actual del usuario';
COMMENT ON COLUMN usuario.ultimo_acceso IS 'Fecha y hora del último acceso al sistema';

-- =============================================
-- Procedimiento: registrar_pago
-- Descripción: Registra un nuevo pago y actualiza el saldo del cliente
-- =============================================

CREATE OR REPLACE PROCEDURE registrar_pago(
    p_cliente_id INTEGER,
    p_monto DECIMAL(10,2),
    p_metodo_pago VARCHAR(50),
    p_concepto VARCHAR(200)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_pago_id INTEGER;
    v_saldo_anterior DECIMAL(10,2);
    v_saldo_nuevo DECIMAL(10,2);
BEGIN
    -- Validar que el cliente exista y esté activo
    IF NOT EXISTS (SELECT 1 FROM cliente WHERE id = p_cliente_id AND estado = 'Activo') THEN
        RAISE EXCEPTION 'Cliente no encontrado o inactivo: %', p_cliente_id;
    END IF;

    -- Validar monto positivo
    IF p_monto <= 0 THEN
        RAISE EXCEPTION 'El monto debe ser mayor a cero: %', p_monto;
    END IF;

    -- Obtener saldo anterior
    SELECT COALESCE(saldo, 0) INTO v_saldo_anterior
    FROM cliente WHERE id = p_cliente_id;

    -- Calcular nuevo saldo
    v_saldo_nuevo := v_saldo_anterior - p_monto;

    -- Insertar el pago
    INSERT INTO pago (cliente_id, monto, metodo_pago, concepto, fecha_pago, estado)
    VALUES (p_cliente_id, p_monto, p_metodo_pago, p_concepto, CURRENT_TIMESTAMP, 'Completado')
    RETURNING id INTO v_pago_id;

    -- Actualizar saldo del cliente
    UPDATE cliente SET saldo = v_saldo_nuevo, updated_at = CURRENT_TIMESTAMP
    WHERE id = p_cliente_id;

    -- Generar comprobante
    INSERT INTO comprobante (pago_id, cliente_id, monto, concepto, fecha_emision)
    VALUES (v_pago_id, p_cliente_id, p_monto, p_concepto, CURRENT_TIMESTAMP);

    -- Registrar en bitácora
    INSERT INTO bitacora (usuario_id, accion, tabla_afectada, registro_id, detalles)
    VALUES (NULL, 'REGISTRO_PAGO', 'pago', v_pago_id, 
            format('Pago registrado: $%s - Cliente: %s', p_monto, p_cliente_id));

    COMMIT;

    RAISE NOTICE 'Pago registrado exitosamente. ID: %, Nuevo saldo: $%', v_pago_id, v_saldo_nuevo;

EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
$$;

