-- 1. Registrar Pago
CREATE OR REPLACE PROCEDURE registrar_pago(
    p_cliente_id INTEGER,
    p_monto DECIMAL(10,2),
    p_metodo VARCHAR(50)
)
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO pago (cliente_id, monto, metodo_pago, fecha_pago, estado)
    VALUES (p_cliente_id, p_monto, p_metodo, CURRENT_TIMESTAMP, 'Completado');

    UPDATE cliente 
    SET saldo = saldo - p_monto
    WHERE id = p_cliente_id;

    RAISE NOTICE 'Pago registrado: $% para cliente %', p_monto, p_cliente_id;
END;
$$;

-- 2. Generar Reporte de Ventas
CREATE OR REPLACE PROCEDURE generar_reporte_ventas(
    p_fecha_inicio DATE,
    p_fecha_fin DATE
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_total_ventas DECIMAL(10,2);
    v_numero_ventas INTEGER;
BEGIN
    SELECT COUNT(*), COALESCE(SUM(total), 0)
    INTO v_numero_ventas, v_total_ventas
    FROM factura
    WHERE fecha_factura BETWEEN p_fecha_inicio AND p_fecha_fin
        AND estado = 'Pagada';

    RAISE NOTICE 'Reporte de ventas: % ventas por $%', v_numero_ventas, v_total_ventas;
END;
$$;

-- 3. Actualizar Stock
CREATE OR REPLACE PROCEDURE actualizar_stock(
    p_producto_id INTEGER,
    p_cantidad INTEGER,
    p_tipo VARCHAR(20)
)
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_tipo = 'Entrada' THEN
        UPDATE producto SET stock_actual = stock_actual + p_cantidad WHERE id = p_producto_id;
    ELSIF p_tipo = 'Salida' THEN
        UPDATE producto SET stock_actual = stock_actual - p_cantidad WHERE id = p_producto_id;
    END IF;

    INSERT INTO movimiento_inventario (producto_id, tipo_movimiento, cantidad, fecha_movimiento)
    VALUES (p_producto_id, p_tipo, p_cantidad, CURRENT_TIMESTAMP);
END;
$$;

-- 4. Calcular Total Pedido
CREATE OR REPLACE FUNCTION calcular_total_pedido(
    p_pedido_id INTEGER
)
RETURNS DECIMAL(10,2)
LANGUAGE plpgsql
AS $$
DECLARE
    v_total DECIMAL(10,2);
BEGIN
    SELECT SUM(cantidad * precio_unitario)
    INTO v_total
    FROM detalle_pedido
    WHERE pedido_id = p_pedido_id;

    RETURN COALESCE(v_total, 0);
END;
$$;
